import numpy as np
from scipy.stats import gaussian_kde

def tv(x):
    return 0.5*(np.exp(-0.5*((x+2)/0.5)**2)/(0.5*np.sqrt(2*np.pi)) + np.exp(-0.5*(x-2)**2)/np.sqrt(2*np.pi))
g=np.linspace(-6,6,2001); t=tv(g)

def draw(kind, seed=0):
    rng=np.random.default_rng(seed)
    if kind=='halfhalf': return np.r_[rng.normal(-2,.5,1000), rng.normal(2,1,1000)]
    lab=rng.integers(0,2,2000); out=np.empty(2000); m=lab==0
    out[m]=rng.normal(-2,.5,int(m.sum())); out[~m]=rng.normal(2,1,int((~m).sum())); return out

def ise(s,h):
    est=gaussian_kde(s,bw_method=h/s.std(ddof=1)).evaluate(g)
    return np.trapezoid((est-t)**2,g)

def lscv_h(s):
    D=s[:,None]-s[None,:]; n=len(s); sd=s.std(ddof=1)
    def crit(h):
        S=np.exp(-D*D/(2*h*h)).sum()/(h*np.sqrt(2*np.pi))
        return S/n**2 - 2*(S-n/(h*np.sqrt(2*np.pi)))/(n*(n-1))
    hs=np.linspace(0.02*sd*n**-0.2, 1.2*(len(s)*3/4)**-0.2*sd, 120)
    vals=[crit(h) for h in hs]
    i=int(np.argmin(vals)); 
    lo,hi=hs[max(i-1,0)],hs[min(i+1,len(hs)-1)]
    hs2=np.linspace(lo,hi,60); v2=[crit(h) for h in hs2]
    return hs2[int(np.argmin(v2))]

for kind in ['halfhalf','mixed']:
    for seed in [0,1]:
        s=draw(kind,seed)
        h_cv=lscv_h(s); h_sil=(2000*3/4)**-0.2*s.std(ddof=1)
        print(f'{kind:9s} seed{seed}: sil ISE={ise(s,h_sil):.5f} | lscv h={h_cv:.3f} ISE={ise(s,h_cv):.5f}')
